CREATE TABLE IF NOT EXISTS zukan_dispute_cases ( dispute_case_id TEXT PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, resolution_run_id TEXT REFERENCES zukan_resolution_runs(resolution_run_id) ON DELETE SET NULL, opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, details_json TEXT NOT NULL DEFAULT '{}', CHECK (json_valid(details_json)), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE TABLE IF NOT EXISTS zukan_dispute_case_events ( dispute_case_event_id TEXT PRIMARY KEY, dispute_case_id TEXT NOT NULL REFERENCES zukan_dispute_cases(dispute_case_id) ON DELETE RESTRICT, event_type TEXT NOT NULL, event_payload_json TEXT NOT NULL DEFAULT '{}', recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (event_type IN ('opened','under_review','resolved','dismissed','reopened')), CHECK (json_valid(event_payload_json)) ); CREATE TABLE IF NOT EXISTS zukan_correction_requests ( correction_request_id TEXT PRIMARY KEY, dispute_case_id TEXT REFERENCES zukan_dispute_cases(dispute_case_id) ON DELETE SET NULL, subject_id TEXT NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, claim_revision_id TEXT REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE SET NULL, requested_by_subject_id TEXT REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, request_payload_json TEXT NOT NULL, requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (json_valid(request_payload_json)) ); CREATE TABLE IF NOT EXISTS zukan_correction_request_events ( correction_request_event_id TEXT PRIMARY KEY, correction_request_id TEXT NOT NULL REFERENCES zukan_correction_requests(correction_request_id) ON DELETE RESTRICT, event_type TEXT NOT NULL, event_payload_json TEXT NOT NULL DEFAULT '{}', recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (event_type IN ('submitted','under_review','accepted','partially_accepted','rejected','withdrawn')), CHECK (json_valid(event_payload_json)) ); CREATE TABLE IF NOT EXISTS zukan_suppression_requests ( suppression_request_id TEXT PRIMARY KEY, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, requested_action TEXT NOT NULL, requested_by_subject_id TEXT REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, request_reason TEXT NOT NULL, request_payload_json TEXT NOT NULL DEFAULT '{}', requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (target_kind IN ('content_object','value_artifact','claim_revision','projection_snapshot','publication_edition')), CHECK (requested_action IN ('suppress','redact','erase')), CHECK (length(trim(request_reason)) > 0), CHECK (json_valid(request_payload_json)) ); CREATE TABLE IF NOT EXISTS zukan_suppression_request_events ( suppression_request_event_id TEXT PRIMARY KEY, suppression_request_id TEXT NOT NULL REFERENCES zukan_suppression_requests(suppression_request_id) ON DELETE RESTRICT, event_type TEXT NOT NULL, governance_event_id TEXT REFERENCES zukan_content_governance_events(governance_event_id) ON DELETE SET NULL, event_payload_json TEXT NOT NULL DEFAULT '{}', recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (event_type IN ('submitted','under_review','approved','rejected','executed','withdrawn')), CHECK (json_valid(event_payload_json)) ); CREATE TABLE IF NOT EXISTS zukan_survey_events ( survey_event_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT, subject_scope_json TEXT NOT NULL, method_json TEXT NOT NULL, effort_json TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (json_valid(subject_scope_json)), CHECK (json_valid(method_json)), CHECK (json_valid(effort_json)), CHECK (ended_at IS NULL OR ended_at >= started_at) ); CREATE TABLE IF NOT EXISTS zukan_detection_outcomes ( detection_outcome_id TEXT PRIMARY KEY, survey_event_id TEXT NOT NULL REFERENCES zukan_survey_events(survey_event_id) ON DELETE RESTRICT, subject_id TEXT NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, outcome TEXT NOT NULL, evidence_content_object_id TEXT REFERENCES zukan_content_objects(content_object_id) ON DELETE SET NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (outcome IN ('detected','not_detected','indeterminate')), UNIQUE (survey_event_id, subject_id) ); CREATE TABLE IF NOT EXISTS zukan_coverage_assessments ( coverage_assessment_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT, scope_json TEXT NOT NULL, predicate_uri TEXT, predicate_version INTEGER, coverage_status TEXT NOT NULL, derived_from_json TEXT NOT NULL DEFAULT '[]', assessed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (coverage_status IN ('assessed','unassessed','not_applicable')), CHECK (json_valid(scope_json)), CHECK (json_valid(derived_from_json)), CHECK ((predicate_uri IS NULL AND predicate_version IS NULL) OR (predicate_uri IS NOT NULL AND predicate_version IS NOT NULL)), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_zukan_coverage_assessments_scope ON zukan_coverage_assessments(tenant_id, workspace_id, coverage_status, assessed_at DESC); CREATE TRIGGER IF NOT EXISTS trg_zukan_governance_events_no_update BEFORE UPDATE ON zukan_content_governance_events BEGIN SELECT RAISE(ABORT, 'zukan_governance_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_governance_events_no_delete BEFORE DELETE ON zukan_content_governance_events BEGIN SELECT RAISE(ABORT, 'zukan_governance_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_snapshot_status_no_update BEFORE UPDATE ON zukan_snapshot_status_events BEGIN SELECT RAISE(ABORT, 'zukan_snapshot_status_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_snapshot_status_no_delete BEFORE DELETE ON zukan_snapshot_status_events BEGIN SELECT RAISE(ABORT, 'zukan_snapshot_status_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_publication_availability_no_update BEFORE UPDATE ON zukan_publication_availability_events BEGIN SELECT RAISE(ABORT, 'zukan_publication_availability_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_publication_availability_no_delete BEFORE DELETE ON zukan_publication_availability_events BEGIN SELECT RAISE(ABORT, 'zukan_publication_availability_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_rights_evaluations_no_update BEFORE UPDATE ON zukan_rights_evaluations BEGIN SELECT RAISE(ABORT, 'zukan_rights_evaluations_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_rights_evaluations_no_delete BEFORE DELETE ON zukan_rights_evaluations BEGIN SELECT RAISE(ABORT, 'zukan_rights_evaluations_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_dispute_cases_no_update BEFORE UPDATE ON zukan_dispute_cases BEGIN SELECT RAISE(ABORT, 'zukan_dispute_cases_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_dispute_cases_no_delete BEFORE DELETE ON zukan_dispute_cases BEGIN SELECT RAISE(ABORT, 'zukan_dispute_cases_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_dispute_case_events_no_update BEFORE UPDATE ON zukan_dispute_case_events BEGIN SELECT RAISE(ABORT, 'zukan_dispute_case_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_dispute_case_events_no_delete BEFORE DELETE ON zukan_dispute_case_events BEGIN SELECT RAISE(ABORT, 'zukan_dispute_case_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_correction_requests_no_update BEFORE UPDATE ON zukan_correction_requests BEGIN SELECT RAISE(ABORT, 'zukan_correction_requests_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_correction_requests_no_delete BEFORE DELETE ON zukan_correction_requests BEGIN SELECT RAISE(ABORT, 'zukan_correction_requests_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_correction_request_events_no_update BEFORE UPDATE ON zukan_correction_request_events BEGIN SELECT RAISE(ABORT, 'zukan_correction_request_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_correction_request_events_no_delete BEFORE DELETE ON zukan_correction_request_events BEGIN SELECT RAISE(ABORT, 'zukan_correction_request_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_suppression_requests_no_update BEFORE UPDATE ON zukan_suppression_requests BEGIN SELECT RAISE(ABORT, 'zukan_suppression_requests_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_suppression_requests_no_delete BEFORE DELETE ON zukan_suppression_requests BEGIN SELECT RAISE(ABORT, 'zukan_suppression_requests_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_suppression_request_events_no_update BEFORE UPDATE ON zukan_suppression_request_events BEGIN SELECT RAISE(ABORT, 'zukan_suppression_request_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_suppression_request_events_no_delete BEFORE DELETE ON zukan_suppression_request_events BEGIN SELECT RAISE(ABORT, 'zukan_suppression_request_events_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_detection_outcomes_no_update BEFORE UPDATE ON zukan_detection_outcomes BEGIN SELECT RAISE(ABORT, 'zukan_detection_outcomes_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_detection_outcomes_no_delete BEFORE DELETE ON zukan_detection_outcomes BEGIN SELECT RAISE(ABORT, 'zukan_detection_outcomes_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_coverage_assessments_no_update BEFORE UPDATE ON zukan_coverage_assessments BEGIN SELECT RAISE(ABORT, 'zukan_coverage_assessments_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_coverage_assessments_no_delete BEFORE DELETE ON zukan_coverage_assessments BEGIN SELECT RAISE(ABORT, 'zukan_coverage_assessments_immutable'); END;
